package dev.algorithmlearning.api.problems.data;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="problems") class ProblemEntity {
 @Id UUID id; @Column(name="user_id") UUID userId; String title, platform; @Column(name="external_problem_id") String externalProblemId; @Column(name="external_url") String externalUrl; String difficulty, description, notes; @Column(name="key_insight") String keyInsight; @Column(name="time_complexity") String timeComplexity; @Column(name="space_complexity") String spaceComplexity; String mistakes; @Column(name="interview_notes") String interviewNotes; @Column(name="created_at") Instant createdAt; @Column(name="updated_at") Instant updatedAt;
 protected ProblemEntity(){} ProblemEntity(UUID id,UUID userId,String title,String platform,String externalProblemId,String externalUrl,String difficulty,String description,String notes,String keyInsight,String timeComplexity,String spaceComplexity,String mistakes,String interviewNotes,Instant createdAt,Instant updatedAt){this.id=id;this.userId=userId;this.title=title;this.platform=platform;this.externalProblemId=externalProblemId;this.externalUrl=externalUrl;this.difficulty=difficulty;this.description=description;this.notes=notes;this.keyInsight=keyInsight;this.timeComplexity=timeComplexity;this.spaceComplexity=spaceComplexity;this.mistakes=mistakes;this.interviewNotes=interviewNotes;this.createdAt=createdAt;this.updatedAt=updatedAt;}
}
